// Core tests: every case in fixtures.json executed literally (expected
// values taken verbatim from the file, never generated by the product),
// plus the SPEC §5 table-integrity, arithmetic cross-check, and
// validation-order suites. Every hand-written expected value below was
// derived by hand from the SPEC's rules or by an independent exact
// rational evaluation — never from the implementation's output.

import assert from "node:assert/strict";
import test from "node:test";
import { DEFAULTS, FIELDS, MAX_ACTIVITIES, RAW_LIMITS, run } from "../public/js/core/calculate.mjs";
import { ACTIVITY_TABLE, formatMet } from "../public/js/core/table.mjs";
import fixtures from "./fixtures.json" with { type: "json" };

const successCases = fixtures.filter((entry) => entry.expected !== undefined);
const failureCases = fixtures.filter(
  (entry) => entry.expectedError !== undefined && entry.kind !== "controller",
);
const controllerCases = fixtures.filter((entry) => entry.kind === "controller");

for (const entry of successCases) {
  test(`fixture ${entry.id}`, () => {
    assert.deepEqual(run(entry.input), { ok: true, result: entry.expected });
  });
}

for (const entry of failureCases) {
  test(`fixture ${entry.id}`, () => {
    assert.deepEqual(run(entry.input), { ok: false, error: entry.expectedError });
  });
}

test("fixture set shape: 23 cases, 8 success, 12 error, 3 controller", () => {
  assert.equal(fixtures.length, 23);
  assert.equal(successCases.length, 8);
  assert.equal(failureCases.length, 12);
  assert.equal(controllerCases.length, 3);
});

// Table integrity (§5.2): the implementation's table equals §2.4 exactly.
test("table integrity: 14 rows in SPEC order with exact ids, codes, MET and names", () => {
  const expected = [
    { id: "walking-moderate", code: "17190", metTenths: 38, nameZh: "步行（中等速度）", nameEn: "Walking, 2.8 to 3.4 mph, moderate pace" },
    { id: "walking-brisk", code: "17200", metTenths: 48, nameZh: "步行（快走）", nameEn: "Walking, 3.5 to 3.9 mph, brisk pace" },
    { id: "hiking-cross-country", code: "17080", metTenths: 60, nameZh: "健行（越野）", nameEn: "Hiking, cross country" },
    { id: "jogging-general", code: "12020", metTenths: 75, nameZh: "慢跑（一般）", nameEn: "Jogging, general" },
    { id: "running-6mph", code: "12050", metTenths: 93, nameZh: "跑步（6.0–6.3 mph）", nameEn: "Running, 6.0 to 6.3 mph (10 min/mile)" },
    { id: "bicycling-leisure", code: "01010", metTenths: 40, nameZh: "自行車（休閒，<10 mph）", nameEn: "Bicycling, <10 mph, leisure" },
    { id: "bicycling-moderate", code: "01030", metTenths: 80, nameZh: "自行車（中速，12–13.9 mph）", nameEn: "Bicycling, 12 to 13.9 mph, moderate effort" },
    { id: "swimming-laps-slow", code: "18240", metTenths: 58, nameZh: "游泳（自由式，慢速）", nameEn: "Swimming laps, freestyle, slow, recreational" },
    { id: "swimming-laps-fast", code: "18230", metTenths: 98, nameZh: "游泳（自由式，快速）", nameEn: "Swimming laps, freestyle, fast, vigorous effort" },
    { id: "aerobic-general", code: "02000", metTenths: 73, nameZh: "有氧運動（一般）", nameEn: "Aerobic, general" },
    { id: "elliptical-moderate", code: "02048", metTenths: 50, nameZh: "橢圓機（中等強度）", nameEn: "Elliptical trainer, moderate effort" },
    { id: "resistance-training", code: "02054", metTenths: 35, nameZh: "重量訓練（多動作，8–15 下）", nameEn: "Resistance (weight) training, multiple exercises, 8–15 reps" },
    { id: "yoga-hatha", code: "02150", metTenths: 23, nameZh: "瑜伽（哈達）", nameEn: "Yoga, Hatha" },
    { id: "tai-chi", code: "15670", metTenths: 33, nameZh: "太極／氣功", nameEn: "Tai chi, qi gong, general" },
  ];
  assert.deepEqual(ACTIVITY_TABLE, expected);
  for (const row of ACTIVITY_TABLE) {
    assert.equal(typeof row.code, "string");
    assert.equal(row.code.length, 5);
  }
  // Leading zeroes survive: the three codes starting with 0.
  assert.deepEqual(
    ACTIVITY_TABLE.filter((row) => row.code.startsWith("0")).map((row) => row.id),
    ["bicycling-leisure", "bicycling-moderate", "aerobic-general", "elliptical-moderate", "resistance-training", "yoga-hatha"],
  );
  // No 2011 value anywhere: brisk walking 4.3, jogging 7.0, running
  // 6 mph 9.8, Hatha yoga 2.5.
  const byId = new Map(ACTIVITY_TABLE.map((row) => [row.id, row]));
  assert.equal(byId.get("walking-brisk").metTenths, 48);
  assert.equal(byId.get("jogging-general").metTenths, 75);
  assert.equal(byId.get("running-6mph").metTenths, 93);
  assert.equal(byId.get("yoga-hatha").metTenths, 23);
  assert.equal(formatMet(60), "6.0");
  assert.equal(formatMet(38), "3.8");
});

// Independent exact-rational evaluation of MET × kg × minutes / 60 with
// half-up rounding, using BigInt throughout (a different route from the
// implementation's Number integer rule). Parsing is by string splitting,
// never by binary floating point.
function parseScaled(raw, fractionDigits) {
  const dot = raw.indexOf(".");
  const intPart = dot === -1 ? raw : raw.slice(0, dot);
  const fracPart = dot === -1 ? "" : raw.slice(dot + 1);
  let value = 0n;
  for (const ch of intPart) value = value * 10n + BigInt(ch.charCodeAt(0) - 48);
  value *= 10n ** BigInt(fractionDigits);
  for (let i = 0; i < fractionDigits; i += 1) {
    const digit = i < fracPart.length ? BigInt(fracPart.charCodeAt(i) - 48) : 0n;
    value += digit * 10n ** BigInt(fractionDigits - 1 - i);
  }
  return value;
}

function independentKcal(metTenths, weight, durationMinutes) {
  const numerator =
    BigInt(metTenths) * parseScaled(weight, 2) * parseScaled(durationMinutes, 1);
  const quotient = numerator / 600000n;
  const remainder = numerator % 600000n;
  return Number(quotient + (2n * remainder >= 600000n ? 1n : 0n));
}

test("arithmetic cross-check: integer rule vs independent exact-rational evaluation", () => {
  const weights = ["20", "20.01", "55.55", "62.5", "99.99", "250", "500"];
  const durations = ["1", "1.5", "30", "45.5", "719.9", "1440"];
  let checked = 0;
  for (const activity of ACTIVITY_TABLE) {
    for (const weight of weights) {
      for (const duration of durations) {
        const outcome = run({ weight, durationMinutes: duration, activities: [activity.id] });
        assert.equal(outcome.ok, true);
        assert.equal(
          outcome.result.rows[0].kcal,
          independentKcal(activity.metTenths, weight, duration),
          `${activity.id} ${weight} kg ${duration} min`,
        );
        assert.equal(outcome.result.rows[0].met, formatMet(activity.metTenths));
        assert.equal(outcome.result.totalKcal, outcome.result.rows[0].kcal);
        checked += 1;
      }
    }
  }
  assert.equal(checked, 14 * 7 * 6);
});

test("arithmetic cross-check: exact ties round up at several scales", () => {
  // Exact ties (fractional part exactly 0.5) found by scanning the
  // independent rule: numerator mod 600000 == 300000.
  let ties = 0;
  const weights = ["20", "25", "40", "65", "80", "100", "130", "200"];
  const durations = ["10", "30", "60", "120"];
  for (const activity of ACTIVITY_TABLE) {
    for (const weight of weights) {
      for (const duration of durations) {
        const numerator =
          BigInt(activity.metTenths) * parseScaled(weight, 2) * parseScaled(duration, 1);
        if (numerator % 600000n !== 300000n) continue;
        ties += 1;
        const quotient = Number(numerator / 600000n);
        const outcome = run({ weight, durationMinutes: duration, activities: [activity.id] });
        assert.equal(outcome.ok, true);
        assert.equal(outcome.result.rows[0].kcal, quotient + 1, `${activity.id} ${weight} ${duration}`);
      }
    }
  }
  assert.ok(ties >= 5, `expected several exact ties in the scan, found ${ties}`);
  // The pinned tie from §2.6, stated literally.
  assert.deepEqual(run({ weight: "65", durationMinutes: "30", activities: ["elliptical-moderate"] }), {
    ok: true,
    result: {
      rows: [{ activityId: "elliptical-moderate", code: "02048", met: "5.0", kcal: 163 }],
      totalKcal: 163,
    },
  });
});

test("compare mode: rows keep input order and the total is the sum of rounded rows", () => {
  const outcome = run({
    weight: "50",
    durationMinutes: "40",
    activities: ["tai-chi", "swimming-laps-fast", "yoga-hatha"],
  });
  assert.equal(outcome.ok, true);
  // tai-chi 3.3 × 50 × 40/60 = 110; fast swim 9.8 × 50 × 40/60 =
  // 326.666… → 327; yoga 2.3 × 50 × 40/60 = 76.666… → 77.
  assert.deepEqual(outcome.result.rows, [
    { activityId: "tai-chi", code: "15670", met: "3.3", kcal: 110 },
    { activityId: "swimming-laps-fast", code: "18230", met: "9.8", kcal: 327 },
    { activityId: "yoga-hatha", code: "02150", met: "2.3", kcal: 77 },
  ]);
  assert.equal(outcome.result.totalKcal, 110 + 327 + 77);
});

const base = { weight: "60", durationMinutes: "30", activities: ["walking-moderate"] };

function errorOf(input) {
  const outcome = run(input);
  assert.equal(outcome.ok, false, `expected an error for ${JSON.stringify(input)}`);
  return outcome.error;
}

test("validation order: schema before fields, weight before duration before activities", () => {
  const schema = { code: "SCHEMA", field: null, row: null };
  assert.deepEqual(errorOf({ ...base, weight: "bad", extra: "1" }), schema);
  assert.deepEqual(errorOf({ weight: "bad", durationMinutes: "bad", activities: ["nope"] }), {
    code: "DECIMAL_FORMAT",
    field: "weight",
    row: null,
  });
  assert.deepEqual(errorOf({ weight: "60", durationMinutes: "bad", activities: ["nope"] }), {
    code: "DECIMAL_FORMAT",
    field: "durationMinutes",
    row: null,
  });
  assert.deepEqual(
    errorOf({ weight: "60", durationMinutes: "30", activities: ["walking-moderate", "bad", "bad", "bad"] }),
    { code: "ROW_LIMIT", field: "activities", row: 4 },
  );
});

test("validation order: capacity before grammar before range", () => {
  assert.deepEqual(errorOf({ ...base, weight: "123456789" }), {
    code: "INPUT_LIMIT",
    field: "weight",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, durationMinutes: "123456789" }), {
    code: "INPUT_LIMIT",
    field: "durationMinutes",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, weight: "60.123" }), {
    code: "DECIMAL_FORMAT",
    field: "weight",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, weight: "19.99" }), {
    code: "RANGE",
    field: "weight",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, weight: "500.01" }), {
    code: "RANGE",
    field: "weight",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, durationMinutes: "0" }), {
    code: "RANGE",
    field: "durationMinutes",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, durationMinutes: "1440.5" }), {
    code: "RANGE",
    field: "durationMinutes",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, durationMinutes: "0.5" }), {
    code: "RANGE",
    field: "durationMinutes",
    row: null,
  });
});

test("grammar: leading zeroes, trailing dot, signs, exponents, units and full-width digits", () => {
  for (const bad of ["00", "01", "60.", ".5", "+60", "-60", "1e2", "60kg", "60 kg", "６０", "60,0", " "]) {
    assert.deepEqual(errorOf({ ...base, weight: bad }), {
      code: "DECIMAL_FORMAT",
      field: "weight",
      row: null,
    });
  }
  for (const bad of ["30.", ".5", "1.25", "30,5"]) {
    assert.deepEqual(errorOf({ ...base, durationMinutes: bad }), {
      code: "DECIMAL_FORMAT",
      field: "durationMinutes",
      row: null,
    });
  }
  // Grammar-valid extremes at both bounds.
  assert.equal(run({ ...base, weight: "20.00" }).ok, true);
  assert.equal(run({ ...base, weight: "500.00" }).ok, true);
  assert.equal(run({ ...base, weight: "0" }).ok, false);
  assert.deepEqual(errorOf({ ...base, weight: "0" }), { code: "RANGE", field: "weight", row: null });
  assert.deepEqual(errorOf({ ...base, weight: "0.00" }), { code: "RANGE", field: "weight", row: null });
  assert.equal(run({ ...base, durationMinutes: "1440" }).ok, true);
  assert.equal(run({ ...base, durationMinutes: "1440.0" }).ok, true);
  assert.equal(run({ ...base, durationMinutes: "1" }).ok, true);
});

test("activities: ROW_LIMIT before element checks, element checks before DUPLICATE", () => {
  assert.deepEqual(
    errorOf({ ...base, activities: ["walking-moderate", "zumba", "jogging-general", "yoga-hatha"] }),
    { code: "ROW_LIMIT", field: "activities", row: 4 },
  );
  assert.deepEqual(errorOf({ ...base, activities: ["yoga-hatha", "yoga-hatha", "zumba"] }), {
    code: "ENUM",
    field: "activities",
    row: 3,
  });
  assert.deepEqual(errorOf({ ...base, activities: ["zumba", "yoga-hatha", "yoga-hatha"] }), {
    code: "ENUM",
    field: "activities",
    row: 1,
  });
  assert.deepEqual(errorOf({ ...base, activities: ["yoga-hatha", "yoga-hatha"] }), {
    code: "DUPLICATE",
    field: "activities",
    row: 2,
  });
  assert.deepEqual(
    errorOf({ ...base, activities: ["walking-moderate", "yoga-hatha", "walking-moderate"] }),
    { code: "DUPLICATE", field: "activities", row: 3 },
  );
});

test("activities: case-sensitive ids, empty element, over-long element, lone surrogate", () => {
  assert.deepEqual(errorOf({ ...base, activities: ["Walking-Moderate"] }), {
    code: "ENUM",
    field: "activities",
    row: 1,
  });
  assert.deepEqual(errorOf({ ...base, activities: ["walking-moderate", ""] }), {
    code: "EMPTY",
    field: "activities",
    row: 2,
  });
  assert.deepEqual(errorOf({ ...base, activities: ["a".repeat(33)] }), {
    code: "INPUT_LIMIT",
    field: "activities",
    row: 1,
  });
  assert.equal(run({ ...base, activities: ["a".repeat(32)] }).ok, false);
  assert.deepEqual(errorOf({ ...base, activities: ["a".repeat(32)] }), {
    code: "ENUM",
    field: "activities",
    row: 1,
  });
  assert.deepEqual(errorOf({ ...base, activities: ["yoga\uD800"] }), {
    code: "UNICODE",
    field: "activities",
    row: 1,
  });
  assert.deepEqual(errorOf({ ...base, weight: "\uD800" }), {
    code: "UNICODE",
    field: "weight",
    row: null,
  });
});

test("schema: extra key, missing key, wrong type, array, null, and accessor are all SCHEMA", () => {
  const schema = { code: "SCHEMA", field: null, row: null };
  assert.deepEqual(errorOf({ ...base, extra: "1" }), schema);
  const missing = { ...base };
  delete missing.activities;
  assert.deepEqual(errorOf(missing), schema);
  assert.deepEqual(errorOf({ ...base, weight: 60 }), schema);
  assert.deepEqual(errorOf({ ...base, durationMinutes: 30 }), schema);
  assert.deepEqual(errorOf({ ...base, activities: "walking-moderate" }), schema);
  assert.deepEqual(errorOf({ ...base, activities: ["walking-moderate", 7] }), schema);
  assert.deepEqual(errorOf(["60"]), schema);
  assert.deepEqual(errorOf(null), schema);
  assert.deepEqual(errorOf("60"), schema);
  assert.deepEqual(errorOf({}), schema);
  const withGetter = { ...base };
  Object.defineProperty(withGetter, "weight", {
    enumerable: true,
    get() {
      return "60";
    },
  });
  assert.deepEqual(errorOf(withGetter), schema);
});

test("core constants: fields, limits, defaults", () => {
  assert.deepEqual(FIELDS, ["weight", "durationMinutes", "activities"]);
  assert.deepEqual(RAW_LIMITS, { weight: 8, durationMinutes: 8, activityElement: 32 });
  assert.equal(MAX_ACTIVITIES, 3);
  assert.deepEqual(DEFAULTS, { weight: "60", durationMinutes: "30", activities: ["walking-moderate"] });
});
